    12  // when io.va is true this checks if the highest priorized map at this
    13  // offset has the same or high permissions set. When there is no map it
    14  // check for the current desc permissions and size.
    15  // when io.va is false it only checks for the desc
    16  R_API bool r_io_is_valid_offset(RIO* io, ut64 offset, int hasperm) {
    17          r_return_val_if_fail (io, false);
    18          if ((io->cache.mode & R_PERM_X) == R_PERM_X) {
    19                  // io.cache must be set to true for this codeblock to be executed
    20                  ut8 word[4] = { 0xff, 0xff, 0xff, 0xff};
    21                  // TODO: check for (io->cache.mode & R_PERM_S) ?
    22                  (void)r_io_read_at (io, offset, (ut8*)&word, 4);
    23                  if (!r_io_cache_read_at (io, offset, (ut8*)&word, 4)) {
    24                          if (!r_io_read_at (io, offset, (ut8*)&word, 4)) {
    25                                  return false;
    26                          }
    27                  }
    28                  return memcmp (word, "\xff\xff\xff\xff", 4) != 0;
    29          }
    30          if (io->mask) {
    31                  if (offset > io->mask && hasperm & R_PERM_X) {
    32                          return false;
    33                  }
    34          }
    35          if (io->va) {
    36                  if (!hasperm) {
    37                          // return r_io_map_is_mapped (io, offset);
    38                          RIOMap* map = r_io_map_get_at (io, offset);
    39                          return map? map->perm & R_PERM_R: false;
    40                  }
    41                  RIOMap* map = r_io_map_get_at (io, offset);
    42                  return map? (map->perm & hasperm) == hasperm: false;
    43          }
    44          if (!io->desc) {
    45                  return false;
    46          }
    47          if (offset > r_io_desc_size (io->desc)) {
    48                  return false;
    49          }
    50          return ((io->desc->perm & hasperm) == hasperm);
    51  }
