    53  // this is wrong, there is more than big and little endian
    54  R_API bool r_io_read_i(RIO* io, ut64 addr, ut64 *val, int size, bool endian) {
    55          ut8 buf[8];
    56          r_return_val_if_fail (io && val, false);
    57          size = R_DIM (size, 1, 8);
    58          if (!r_io_read_at (io, addr, buf, size)) {
    59                  return false;
    60          }
    61          //size says the number of bytes to read transform to bits for r_read_ble
    62          *val = r_read_ble (buf, endian, size * 8);
    63          return true;
    64  }
    65
    66  R_API bool r_io_write_i(RIO* io, ut64 addr, ut64 *val, int size, bool endian) {
    67          ut8 buf[8];
    68          r_return_val_if_fail (io && val, false);
    69          size = R_DIM (size, 1, 8);
    70          //size says the number of bytes to read transform to bits for r_read_ble
    71          r_write_ble (buf, *val, endian, size * 8);
    72          return r_io_write_at (io, addr, buf, size) == size;
    73  }
